"""``chat_messages`` collection (``routes/chat_routes.py``).

The frontend owns the message fields; the backend only adds ``userId``.
Only ``userId`` is validated, other fields are passed through.
"""

from ._validation import document_validator, require_str

COLLECTION = "chat_messages"

FIELDS = {
    "_id": "ObjectId, auto-generated by MongoDB; the API sorts on it for message order.",
    "userId": "str, required. References users.id.",
    "...": "Any other fields sent by the frontend chat component (e.g. role, text).",
}

EXAMPLE = {"userId": "usr-1a2b3c4d5e", "role": "user", "text": "What are the top themes?"}


@document_validator
def validate_chat_message(doc, errors):
    require_str(doc, "userId", errors)
